## Why This Is Asked
This question tests advanced CGO patterns involving callbacks, memory ownership across the FFI boundary, and thread-safe concurrent processing.

## Key Concepts
- **CGO callbacks**: Calling from C into Go functions requires a trampoline due to Go's runtime constraints
- **Memory safety**: Never pass Go pointers directly to C; always copy data into C-allocated or Go-owned memory
- **Worker pools**: Distributing batches across goroutines with proper synchronization and result aggregation
- **Error propagation**: Handling errors across the FFI boundary while maintaining Go's error idioms

## Code Example

```c
// tick.h - C API header
#ifndef TICK_H
#define TICK_H

#include <stddef.h>

typedef struct {
    long long ts;
    double price;
} Tick;

typedef struct {
    long long ts;
    double price;
    int status;
} TickResult;

typedef void (*TickResultCallback)(const TickResult* r, void* ctx);

int process_ticks_async(const Tick* ticks, size_t n, TickResultCallback cb, void* ctx);

#endif
```

```c
// tick.c - Minimal C implementation with callback trampoline
#include "tick.h"
#include <stdlib.h>
#include <string.h>

// Forward declaration for the Go callback bridge
extern void goTickCallback(void* goFunc, const TickResult* r, void* ctx);

static void trampoline(const TickResult* r, void* ctx) {
    void* goFunc = *(void**)ctx;
    goTickCallback(goFunc, r, ctx);
}

int process_ticks_async(const Tick* ticks, size_t n, void (*cb)(const TickResult*, void*), void* ctx) {
    // Store the Go function pointer at the start of ctx for the trampoline
    for (size_t i = 0; i < n; i++) {
        TickResult result = {
            .ts = ticks[i].ts,
            .price = ticks[i].price,
            .status = (ticks[i].price > 0) ? 1 : 0
        };
        cb(&result, ctx);
    }
    return 0;
}
```

```go
// tick_go.go - Go binding with proper memory management
package main

/*
#cgo CFLAGS: -I.
#cgo LDFLAGS: -L. -ltick
#include "tick.h"

//export goTickCallback
static void goTickCallback(void* goFunc, const TickResult* r, void* ctx) {
    // This is a placeholder - actual implementation uses go runtime cgo callbacks
}
*/
import "C"
import (
    "runtime"
    "sync"
    "unsafe"
)

type Tick struct {
    Timestamp int64
    Price     float64
}

type TickResult struct {
    Timestamp int64
    Price     float64
    Status    int
}

type resultCollector struct {
    results []TickResult
    mu      sync.Mutex
    done    chan struct{}
    err     error
}

func ProcessTicks(ticks []Tick) ([]TickResult, error) {
    if len(ticks) == 0 {
        return nil, nil
    }

    collector := &resultCollector{
        results: make([]TickResult, 0, len(ticks)),
        done:    make(chan struct{}),
    }

    // Convert Go slice to C array
    cTicks := (*C.tick)(unsafe.Pointer(&ticks[0]))
    cLen := C.size_t(len(ticks))

    // Use runtime.SetCgoWolfmark for callback registration
    runtime.LockOSThread()

    ret := C.process_ticks_async(
        cTicks,
        cLen,
        C.TickResultCallback(C.tick_result_callback_trampoline),
        unsafe.Pointer(collector),
    )

    if ret != 0 {
        return nil, C.GoString(C.ticker_error())
    }

    <-collector.done
    return collector.results, collector.err
}

//export tick_result_callback_trampoline
func tick_result_callback_trampoline(r *C.tick_result, ctx unsafe.Pointer) {
    collector := (*resultCollector)(ctx)

    // CRITICAL: Copy data into Go-owned memory before any C cleanup
    result := TickResult{
        Timestamp: int64(r.ts),
        Price:     float64(r.price),
        Status:    int(r.status),
    }

    collector.mu.Lock()
    collector.results = append(collector.results, result)
    collector.mu.Unlock()
}
```

```go
// worker_pool.go - Worker pool with batch processing
package main

import (
    "context"
    "errors"
    "fmt"
    "sync"
    "sync/atomic"
)

type BatchResult struct {
    BatchID int
    Results []TickResult
    Err     error
}

type WorkerPool struct {
    workers    int
    resultCh   chan BatchResult
    wg         sync.WaitGroup
    ctx        context.Context
    cancel     context.CancelFunc
}

func NewWorkerPool(workers int, bufferSize int) *WorkerPool {
    ctx, cancel := context.WithCancel(context.Background())
    return &WorkerPool{
        workers:  workers,
        resultCh: make(chan BatchResult, bufferSize),
        ctx:      ctx,
        cancel:   cancel,
    }
}

func (wp *WorkerPool) ProcessBatches(batches [][]Tick) ([]TickResult, error) {
    var totalResults []TickResult
    var wg sync.WaitGroup
    var errCount int32

    for i, batch := range batches {
        select {
        case <-wp.ctx.Done():
            return totalResults, wp.ctx.Err()
        default:
        }

        wg.Add(1)
        go func(batchID int, ticks []Tick) {
            defer wg.Done()

            results, err := ProcessTicks(ticks)
            if err != nil {
                atomic.AddInt32(&errCount, 1)
                wp.resultCh <- BatchResult{
                    BatchID: batchID,
                    Err:     err,
                }
                return
            }

            wp.resultCh <- BatchResult{
                BatchID: batchID,
                Results: results,
            }
        }(i, batch)
    }

    go func() {
        wg.Wait()
        close(wp.resultCh)
    }()

    for result := range wp.resultCh {
        if result.Err != nil {
            return totalResults, fmt.Errorf("batch %d failed: %w", result.BatchID, result.Err)
        }
        totalResults = append(totalResults, result.Results...)
    }

    if errCount > 0 {
        return totalResults, fmt.Errorf("%d batches failed", errCount)
    }

    return totalResults, nil
}

func (wp *WorkerPool) Shutdown() {
    wp.cancel()
    wp.wg.Wait()
}

// Example usage
func main() {
    // Create sample batches
    batches := [][]Tick{
        {{Timestamp: 1000, Price: 100.0}, {Timestamp: 1001, Price: 101.0}},
        {{Timestamp: 1002, Price: 102.0}, {Timestamp: 1003, Price: 103.0}},
    }

    pool := NewWorkerPool(4, len(batches))
    results, err := pool.ProcessBatches(batches)
    if err != nil {
        fmt.Printf("Error: %v\n", err)
        return
    }

    fmt.Printf("Processed %d results\n", len(results))
    pool.Shutdown()
}
```

## Common Pitfalls
1. **Passing Go pointers to C**: Always allocate C memory or copy to Go slices first
2. **Callback thread safety**: Use `runtime.LockOSThread()` for cgo callbacks
3. **Memory lifetime**: Ensure Go slice outlives the C call that references it
4. **Error handling across FFI**: Return error strings from C, convert to Go errors
